<?php
require_once __DIR__.'/../includes/functions.php';require_role('admin');
$exams=db()->query('SELECT * FROM exams ORDER BY exam_id DESC')->fetchAll();$examId=(int)($_GET['exam']??($exams[0]['exam_id']??0));$rows=[];
if($examId){$q=db()->prepare('SELECT s.roll_number,u.name,c.class_name,sub.subject_name,m.obtained_marks,m.total_marks FROM marks m JOIN students s ON s.student_id=m.student_id JOIN users u ON u.user_id=s.user_id JOIN subjects sub ON sub.subject_id=m.subject_id JOIN enrollments en ON en.student_id=s.student_id JOIN classes c ON c.class_id=en.class_id WHERE m.exam_id=? ORDER BY c.class_name,s.roll_number,sub.subject_name');$q->execute([$examId]);$rows=$q->fetchAll();}
include __DIR__.'/../includes/header.php';?>
<div class="card mb-3"><div class="card-header">Filter result report</div><div class="card-body"><form method="get" class="row g-2"><div class="col-md-8"><select class="form-select" name="exam"><?php foreach($exams as $x):?><option value="<?=$x['exam_id']?>" <?=$examId===$x['exam_id']?'selected':''?>><?=e($x['exam_name'].' · '.$x['academic_session'])?></option><?php endforeach;?></select></div><div class="col-md-2"><button class="btn btn-primary w-100">Generate</button></div><div class="col-md-2"><button type="button" onclick="window.print()" class="btn btn-outline-primary w-100">Print / PDF</button></div></form></div></div>
<div class="card"><div class="card-header">Class-wise / subject-wise result data</div><div class="table-responsive"><table class="table mb-0"><thead><tr><th>Class</th><th>Roll no.</th><th>Student</th><th>Subject</th><th>Obtained</th><th>Maximum</th><th>Percentage</th><th>Grade</th></tr></thead><tbody><?php foreach($rows as $r):$pct=$r['total_marks']?($r['obtained_marks']/$r['total_marks']*100):0;?><tr><td><?=e($r['class_name'])?></td><td><?=e($r['roll_number'])?></td><td><?=e($r['name'])?></td><td><?=e($r['subject_name'])?></td><td><?=e((string)$r['obtained_marks'])?></td><td><?=e((string)$r['total_marks'])?></td><td><?=number_format($pct,2)?>%</td><td><?=e(grade_for($pct))?></td></tr><?php endforeach;?></tbody></table></div><?php if(!$rows):?><div class="empty-state">No marks have been entered for this examination yet.</div><?php endif;?></div>
<?php include __DIR__.'/../includes/footer.php';?>
